window.applySceneBackgroundToModal = function(overlayId, sceneKey) {
  const ov = document.getElementById(overlayId);
  if (!ov) return null;
  const card = ov.querySelector('.modal-card');
  const def = window.SCENE_DEFS[sceneKey];
  if (!card || !def) return null;
  const atlasObj = window.SCENE_BG_ATLASES[def.atlas];
  if (!atlasObj || !atlasObj.url) return null;

  const posX = (def.quad % 2) === 0 ? '0%' : '100%';
  const posY = def.quad < 2 ? '0%' : '100%';

  card.classList.add('scene-backed');
  card.style.backgroundImage = `linear-gradient(180deg, ${def.tint} 0%, rgba(7, 12, 20, 0.76) 55%, rgba(6, 10, 17, 0.88) 100%), url("${atlasObj.url}")`;
  card.style.backgroundSize = '100% 100%, 200% 200%';
  card.style.backgroundPosition = `0% 0%, ${posX} ${posY}`;
  return def;
};

// Ermittelt automatisch die passende Nationen- & Gebäude-Szene für jeden Hafen-Tab!
window.resolvePortSceneKey = function(port, tabKey) {
  const fac = (port && port.faction) || 'pirates';
  if (tabKey === 'shipyard') {
    return (fac === 'pirates' || (port && !port.hasLighthouse && port.maxFortHp < 2900)) ? 'shipyard_beach' : 'shipyard_stone';
  }
  if (tabKey === 'armory') return 'armory_foundry';
  if (tabKey === 'market') return 'market_kontor';
  if (tabKey === 'tavern') {
    if (fac === 'pirates') return 'tavern_pirates';
    if (fac === 'spain' || fac === 'france') return 'tavern_spain';
    return 'tavern_colonial';
  }
  if (tabKey === 'gov') {
    if (fac === 'spain') return 'gov_spain';
    if (fac === 'england') return 'gov_england';
    if (fac === 'france') return 'gov_france';
    if (fac === 'netherlands' || fac === 'denmark') return 'gov_merchant';
    return 'gov_pirates';
  }
  return 'shipyard_stone';
};